import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro: RetNet carrier vs external baselines","description":"","frontmatter":{"title":"Retro: RetNet carrier vs external baselines","type":"retro","date":"2026-10-14T00:00:00.000Z"},"headers":[],"relativePath":"graphopt/project/retros/retnet-external-baselines.md","filePath":"vendored/graphopt/project/retros/retnet-external-baselines.md"}`),a={name:`graphopt/project/retros/retnet-external-baselines.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-retnet-carrier-vs-external-baselines" tabindex="-1">Retro: RetNet carrier vs external baselines <a class="header-anchor" href="#retro-retnet-carrier-vs-external-baselines" aria-label="Permalink to “Retro: RetNet carrier vs external baselines”">​</a></h1><p>Date: session of 2026-10-14. Probe: <code>lab/probes/retnet_baseline_probe.py</code> (committed <code>6eca509</code>). Dev box: RTX 2050-class GPU, fp64 unless noted.</p><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to “Why this exists”">​</a></h2><p>The README&#39;s &quot;7.30x less memory&quot; row was measured against <em>our own</em> spelled-quadratic <code>_ChunkedRetention</code> reference — not against the RetNet paper&#39;s implementation or tuned third-party kernels. This probe re-measures the delivered K-way carrier against external baselines. Verdict below is honest: the carrier is the paper&#39;s algorithm, and the hand-tuned world still beats our artifact.</p><h2 id="arms" tabindex="-1">Arms <a class="header-anchor" href="#arms" aria-label="Permalink to “Arms”">​</a></h2><ul><li><code>spelled-eager</code> / <code>spelled-compiled</code> — the optimize-input model.</li><li><code>carrier</code> (fp64) / <code>carrier32</code> (fp32) — extracted + lowered K-way carrier.</li><li><code>paper-eqn</code> — faithful in-script reimplementation of Sun et al.&#39;s chunkwise recurrence, gamma matched (0.9), no stability rescale.</li><li><code>paper-code</code> — official <code>torchscale</code> <code>chunk_recurrent_forward</code> driven directly (<code>inner_mask</code> inlined verbatim from <code>RetNetRelPos.forward</code>, decay patched to log(0.9)).</li><li><code>fla-chunk</code> / <code>fla-rec</code> — fla-org <code>chunk_retention</code> / <code>fused_recurrent_retention</code>, fp32 (Triton).</li></ul><h2 id="numbers-t-2048-k-8-c-256" tabindex="-1">Numbers (T=2048, K=8, C=256) <a class="header-anchor" href="#numbers-t-2048-k-8-c-256" aria-label="Permalink to “Numbers (T=2048, K=8, C=256)”">​</a></h2><pre><code>spelled-eager     169.92 MiB   21.73 ms   1.00x
spelled-compiled   73.90 MiB   27.01 ms   2.30x
carrier            30.01 MiB    3.14 ms   5.66x
paper-eqn          26.91 MiB    2.12 ms   6.32x
paper-code         27.44 MiB    3.00 ms   6.19x
carrier32          19.45 MiB    2.38 ms   8.73x
fla-chunk           9.96 MiB    0.28 ms  17.05x
fla-rec            10.15 MiB    1.16 ms  16.74x
</code></pre><p>T=512 / T=1024 same ordering; carrier loses at 512, crosses ~1024.</p><h2 id="numerics" tabindex="-1">Numerics <a class="header-anchor" href="#numerics" aria-label="Permalink to “Numerics”">​</a></h2><ul><li>carrier vs spelled-eager: 9.8e-9 fp64 — the delivery is correct.</li><li>carrier vs paper-eqn: 9.8e-9 fp64 — <strong>the extracted program IS the paper&#39;s chunkwise algorithm</strong>, not an approximation of it.</li><li>carrier vs paper-code: ~0.5 — the official impl applies an <code>all_scale</code> row-normalization (fp16 stability) that is NOT an exact identity; its output differs from raw retention by construction. Worth knowing if anyone compares against torchscale outputs.</li></ul><h2 id="what-this-means-for-the-claims" tabindex="-1">What this means for the claims <a class="header-anchor" href="#what-this-means-for-the-claims" aria-label="Permalink to “What this means for the claims”">​</a></h2><ol><li>&quot;Beats its own input&quot; — yes, decisively (5.66x memory, 6.9x speed at T=2048; 2.5x memory and ~8.6x speed vs the input under torch.compile — compile fixes fusion, not asymptotics).</li><li>&quot;Beats the paper&#39;s chunkwise impl&quot; — no: ~1.1x more memory, ~1.5x slower than a plain hand-written chunked loop.</li><li>&quot;Beats tuned kernels&quot; — no: FLA is ~3x less memory and ~11x faster. That gap is <em>lowering quality</em> — our artifact is a general lowering of the extracted term (many small ops, materialized decay vectors), not a fused scan kernel.</li><li>&quot;A new transformation&quot; — no: it is the paper&#39;s published duality, machine-rederived and machine-verified.</li></ol><p>The defensible claim stands at: certified mechanical reachability of a published linearization + delivery as a verified runnable module. Closing the FLA gap is a <em>lowering/kernel</em> problem (genkernel/fusion), not a semantics problem — a separate dimension by ADR 0003.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};